 [Serializable]public class R12Trial {public R12Spec spec;public string launch,final;public List<BreakRecord> breaks=new List<BreakRecord>();public List<R12Reclaim> claims=new List<R12Reclaim>();public float launchBudget,spent,maxSpeed,maxSpin;public int physicalTicks;public bool resetClean;}
 [Serializable]public class R12Report {public string revision="r12-progression1",state="RUNNING",method="Native normal initialization and 601 active charge ticks, no teleport/pose override. r11 / identical new-layout-no-refill / new-layout-refill distinguish layout and refill. Natural input variation is separate from same-input retry. No browser hand operation or listening claim.";public List<R12Trial> trials=new List<R12Trial>();}
 [UnityTest]public IEnumerator R12Progression(){Directory.CreateDirectory(Evidence);string path=Path.Combine(Evidence,"progression.json");Assert.That(File.Exists(path),Is.False);var report=new R12Report();Action save=()=>File.WriteAllText(path,JsonUtility.ToJson(report,true));save();
 foreach(var spec in new[]{new R12Spec{id="r11-fast35",angle=35,route=false,reclaim=false},new R12Spec{id="r12-layout-no-refill",angle=35,reclaim=false},new R12Spec{id="r12-fast35",angle=35},new R12Spec{id="r12-standard",angle=12,level=0,rate=2},new R12Spec{id="r12-high65",angle=65},new R12Spec{id="r12-left35",angle=35,direction=-1}}){yield return NewRetrySubject(false,true,true,true,true,true,spec.route);var w=Field(current,"world");w.GetType().GetField("UseProgressionR12").SetValue(w,spec.reclaim);StartRouteChargeR11(spec.angle,spec.level,spec.rate,spec.direction);var sim=Property(current,"ReviewSimulation");var row=new R12Trial{spec=spec,launch=JsonUtility.ToJson(Field(State(current),"launchReceipt")),launchBudget=Convert.ToSingle(Property(sim,"RotorCapacity"))};report.trials.Add(row);save();var marks=new[]{280f,850,1370,1630,2110,2740,3180};int index=0,claims=0;
 for(int i=0;i<11000&&!(bool)Property(current,"Finished");i++){Call(current,"Tick",1f/60);row.physicalTicks++;var state=State(current);row.maxSpeed=Mathf.Max(row.maxSpeed,F(state,"speed"));row.maxSpin=Mathf.Max(row.maxSpin,Mathf.Abs(F(state,"spinRps")));if(index<marks.Length&&F(state,"distance")>marks[index]){CaptureRoute(spec.id,"x"+marks[index]);index++;}int now=Convert.ToInt32(Field(state,"rechargeCount"));if(now>claims&&claims==0)CaptureRoute(spec.id,"first-reclaim");claims=now;}
 row.final=JsonUtility.ToJson(State(current));row.spent=Convert.ToSingle(Property(sim,"OverdriveSpent"));foreach(var e in (IEnumerable)Field(sim,"BreakEvents"))row.breaks.Add(new BreakRecord{id=(string)Field(e,"id"),material=(string)Field(e,"material"),secondary=(bool)Field(e,"secondary"),time=F(e,"time"),position=(Vector3)Field(e,"position")});foreach(var e in (IEnumerable)Field(sim,"ReclaimEventsR12"))row.claims.Add(JsonUtility.FromJson<R12Reclaim>(JsonUtility.ToJson(e)));CaptureRoute(spec.id,"result");save();
 Assert.That((bool)Property(current,"Finished"),Is.True,spec.id);Assert.That((string)Field(State(current),"physicsFault"),Is.Empty,spec.id);Assert.That(row.claims.Select(x=>x.id).Distinct().Count(),Is.EqualTo(row.claims.Count));Assert.That(row.claims.All(x=>row.breaks.Any(b=>b.id==x.id)),Is.True);Assert.That(row.claims.All(x=>Mathf.Abs(x.after-x.before-x.joules)<.1f),Is.True);Assert.That(row.spent,Is.LessThanOrEqualTo(row.launchBudget+row.claims.Sum(x=>x.joules)+.1f));Assert.That(Convert.ToSingle(Property(sim,"RotorRemaining")),Is.GreaterThanOrEqualTo(-.01f));
 if(spec.id=="r12-standard"){Call(current,"SetReducedMotion","1");Call(current,"RetryLaunch","");Assert.That(Convert.ToInt32(Field(State(current),"rechargeCount")),Is.EqualTo(0));var retry=new R12Trial{spec=new R12Spec{id="r12-standard-reduced-retry",angle=12,level=0,rate=2},launch=JsonUtility.ToJson(Field(State(current),"launchReceipt"))};report.trials.Add(retry);for(int i=0;i<11000&&!(bool)Property(current,"Finished");i++)Call(current,"Tick",1f/60);retry.final=JsonUtility.ToJson(State(current));save();Assert.That((bool)Property(current,"Finished"),Is.True);Assert.That((string)Field(State(current),"physicsFault"),Is.Empty);Call(current,"Prepare","");row.resetClean=F(State(current),"time")==0&&Convert.ToInt32(Field(State(current),"rechargeCount"))==0&&Convert.ToInt32(Field(State(current),"destructionEvent"))==0;Assert.That(row.resetClean,Is.True);save();}
 Call(current,"ShutdownReviewPhysics");current=null;yield return null;yield return null;}
 report.state="COMPLETED";save();}

 void CaptureMotionR12(int index){using(var scope=new RenderIsolation(current.gameObject.scene,(UnityEngine.SceneManagement.Scene)Property(Property(current,"ReviewSimulation"),"Scene"))){var c=(Camera)Property(current,"ReviewCamera");var previous=RenderTexture.active;var rt=new RenderTexture(844,390,24);rt.Create();c.targetTexture=rt;RenderTexture.active=rt;c.Render();var image=new Texture2D(844,390,TextureFormat.RGB24,false);image.ReadPixels(new Rect(0,0,844,390),0,0);image.Apply();var folder=Path.Combine(Evidence,"motion");Directory.CreateDirectory(folder);File.WriteAllBytes(Path.Combine(folder,index.ToString("D5")+".png"),image.EncodeToPNG());c.targetTexture=null;RenderTexture.active=previous;UnityEngine.Object.DestroyImmediate(image);rt.Release();UnityEngine.Object.DestroyImmediate(rt);}}
 [UnityTest]public IEnumerator R12FinalArtAndFlow(){
 Directory.CreateDirectory(Evidence);yield return NewRetrySubject(false,true,true,true,true,true,true);StartRouteChargeR11(35,3,6);bool captured=false;int frames=0;var report=new R12Report{revision="r12-progression1-backdrop-repair1"};var row=new R12Trial{spec=new R12Spec{id="r12-final-fast35",angle=35},launch=JsonUtility.ToJson(Field(State(current),"launchReceipt"))};report.trials.Add(row);
 for(int tick=0;tick<11000&&!(bool)Property(current,"Finished");tick++){
 Call(current,"Tick",1f/60);var state=State(current);float distance=F(state,"distance");
 if(tick%5==0&&((distance>=1500&&distance<1750)||(distance>=2700&&distance<2920)))CaptureMotionR12(frames++);
 if(!captured&&distance>1630){var ground=current.GetComponentsInChildren<Transform>(true).Where(x=>x.name=="route ground").ToArray();Assert.That(ground.Length,Is.EqualTo(2));foreach(var g in ground){g.localPosition=new Vector3(g.localPosition.x,-.2f,8);g.localScale=new Vector3(1700,.3f,26);}CaptureRoute("r12-country-ground-before","same-pose");foreach(var g in ground){g.localPosition=new Vector3(g.localPosition.x,-.2f,110);g.localScale=new Vector3(1700,.3f,230);}CaptureRoute("r12-country-ground-after","same-pose");captured=true;}
 }
 Assert.That(captured,Is.True);Assert.That((bool)Property(current,"Finished"),Is.True);Assert.That((string)Field(State(current),"physicsFault"),Is.Empty);row.final=JsonUtility.ToJson(State(current));CaptureRoute("r12-final","result");
 Call(current,"SetPaused","1");float clock=F(State(current),"time");Call(current,"Tick",.1f);Assert.That(F(State(current),"time"),Is.EqualTo(clock));Call(current,"SetPaused","0");Call(current,"RetryLaunch","");Assert.That(Convert.ToInt32(Field(State(current),"rechargeCount")),Is.EqualTo(0));Assert.That(Convert.ToInt32(Field(State(current),"destructionEvent")),Is.EqualTo(0));Assert.That(F(State(current),"hitStopRemaining"),Is.EqualTo(0));Assert.That(F(State(current),"worldLifeAge"),Is.EqualTo(0));CaptureRoute("r12-final","retry");Call(current,"Prepare","");Assert.That(F(State(current),"time"),Is.EqualTo(0));Assert.That(Convert.ToInt32(Field(State(current),"rechargeCount")),Is.EqualTo(0));report.state="COMPLETED";File.WriteAllText(Path.Combine(Evidence,"final-art-flow.json"),JsonUtility.ToJson(report,true));File.WriteAllText(Path.Combine(Evidence,"motion-info.json"),"{\"method\":\"Native game RenderTexture, 12 fps sampling of Tick(1/60), two naturally reached excerpts with a cut; no DOM HUD, no audio, no hand input\",\"fps\":12,\"frames\":"+frames+"}");Call(current,"ShutdownReviewPhysics");current=null;yield return null;
 }
